Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$ExpectedBranch = "feature/vitrine-marketplace"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDir = Join-Path $Root ".orcaly-paid-revenue-backup-$Timestamp"
$PatchFile = Join-Path $env:TEMP "orcaly-paid-revenue-$Timestamp.js"

$TouchedFiles = @(
  "lib\order-status.ts",
  "app\painel\inicio\page.tsx",
  "app\painel\pedidos\page.tsx",
  "app\painel\pedidos\[id]\page.tsx"
)

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
  throw "Execute este script na raiz do projeto Orçaly."
}

$Branch = (& git branch --show-current | Out-String).Trim()

if ($Branch -ne $ExpectedBranch) {
  throw "Branch atual: $Branch. Use $ExpectedBranch."
}

New-Item -ItemType Directory -Force -Path $BackupDir | Out-Null

$ExistingBefore = @{}

foreach ($RelativePath in $TouchedFiles) {
  $Source = Join-Path $Root $RelativePath
  $ExistingBefore[$RelativePath] = Test-Path -LiteralPath $Source

  if ($ExistingBefore[$RelativePath]) {
    $Destination = Join-Path $BackupDir $RelativePath
    New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
    Copy-Item -LiteralPath $Source -Destination $Destination -Force
  }
}

function Restore-OrcalyPaidRevenueBackup {
  Write-Host ""
  Write-Host "Restaurando arquivos anteriores..." -ForegroundColor Yellow

  foreach ($RelativePath in $TouchedFiles) {
    $Backup = Join-Path $BackupDir $RelativePath
    $Destination = Join-Path $Root $RelativePath

    if ($ExistingBefore[$RelativePath]) {
      if (Test-Path -LiteralPath $Backup) {
        New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
        Copy-Item -LiteralPath $Backup -Destination $Destination -Force
      }
    }
    elseif (Test-Path -LiteralPath $Destination) {
      Remove-Item -LiteralPath $Destination -Force
    }
  }
}

try {
  $EncodedPatch = @'

'@

  $PatchBytes = [Convert]::FromBase64String(($EncodedPatch -replace "\s", ""))
  [IO.File]::WriteAllBytes($PatchFile, $PatchBytes)

  Write-Host "==> Corrigindo faturamento e status de pedidos" -ForegroundColor Cyan

  node $PatchFile
  $PatchExitCode = $LASTEXITCODE

  Write-Host ""
  Write-Host "PATCH_NODE_EXIT_CODE=$PatchExitCode" -ForegroundColor Yellow

  if ($PatchExitCode -ne 0) {
    throw "O patch financeiro falhou."
  }

  $Checks = @(
    @("lib\order-status.ts", "ORCALY_ORDER_STATUS_V1"),
    @("lib\order-status.ts", "Aguardando pagamento"),
    @("app\painel\inicio\page.tsx", "ORCALY_PAID_REVENUE_V1"),
    @("app\painel\inicio\page.tsx", "paidTodayOrders"),
    @("app\painel\pedidos\page.tsx", "ORCALY_PAID_ORDERS_METRICS_V1"),
    @("app\painel\pedidos\page.tsx", "Faturamento confirmado"),
    @("app\painel\pedidos\[id]\page.tsx", "ORCALY_PAYMENT_AWARE_ORDER_DETAIL_V1"),
    @("app\painel\pedidos\[id]\page.tsx", "paymentConfirmed")
  )

  Write-Host ""
  Write-Host "==> Verificando correções" -ForegroundColor Cyan

  foreach ($Check in $Checks) {
    $Found = Select-String `
      -LiteralPath (Join-Path $Root $Check[0]) `
      -Pattern $Check[1] `
      -SimpleMatch `
      -ErrorAction SilentlyContinue

    if (-not $Found) {
      throw "Verificação falhou: $($Check[0]) -> $($Check[1])"
    }

    Write-Host "[OK] $($Check[1])" -ForegroundColor Green
  }

  Write-Host ""
  Write-Host "==> Verificando diff" -ForegroundColor Cyan

  git --no-pager diff --check -- @($TouchedFiles)

  if ($LASTEXITCODE -ne 0) {
    throw "git diff --check encontrou problemas."
  }

  Remove-Item `
    -LiteralPath (Join-Path $Root ".next") `
    -Recurse `
    -Force `
    -ErrorAction SilentlyContinue

  Write-Host ""
  Write-Host "==> Executando build completo" -ForegroundColor Cyan

  npm run build
  $BuildExitCode = $LASTEXITCODE

  Write-Host ""
  Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

  if ($BuildExitCode -ne 0) {
    throw "O build falhou."
  }

  Remove-Item -LiteralPath $BackupDir -Recurse -Force
  Remove-Item -LiteralPath $PatchFile -Force -ErrorAction SilentlyContinue

  Write-Host ""
  Write-Host "==================================================" -ForegroundColor Green
  Write-Host "FATURAMENTO E STATUS CORRIGIDOS" -ForegroundColor Green
  Write-Host "==================================================" -ForegroundColor Green
  Write-Host "Faturamento: somente pagamentos confirmados"
  Write-Host "Pendente: Aguardando pagamento"
  Write-Host "Falha: Pagamento não aprovado"
  Write-Host "Cancelado: Pagamento cancelado"
  Write-Host "Fluxo: inicia somente após pagamento"
  Write-Host ""
  Write-Host "Nenhum commit, push ou deploy foi criado."
}
catch {
  Restore-OrcalyPaidRevenueBackup
  Remove-Item -LiteralPath $PatchFile -Force -ErrorAction SilentlyContinue
  Remove-Item -LiteralPath $BackupDir -Recurse -Force -ErrorAction SilentlyContinue
  throw
}
